    public_input_explainer_open: "Kijan patisipasyon piblik la mache",
    public_input_explainer_what_html: "<p>Patisipe nan yon pwosedi piblik vle di kite yon bagay nan yon dosye ofisyèl: pale nan yon odyans, oswa voye yon kòmantè ekri anvan yon dat limit ki pibliye. Sa dosye sa a fè apre depann de pwosedi a, epi chak anons sou sit sa a di kilès ki aplike pou li.</p>",
    public_input_explainer_destinations_heading: "Kote sa ou di a rive nan fen",
    public_input_explainer_destinations_html: "<ul><li><b>Yon dosye kòmantè piblik</b> — yon kòmantè ekri ki depoze pandan yon peryòd kòmantè antre nan dosye enstitisyon an dwe konsidere.</li><li><b>Temwayaj odyans</b> — sa ou di nan yon odyans antre nan dosye temwayaj odyans sa a.</li><li><b>Yon transkripsyon</b> — kèk pwosedi pibliye yon rapò mo pou mo sou sesyon an.</li><li><b>Pwosè vèbal</b> — lòt enstitisyon pibliye yon rezime sa ki pase a olye.</li><li><b>Yon dokiman desizyon</b> — yon dosye apa, ki pibliye lè enstitisyon an anrejistre yon desizyon.</li></ul><p>Kèk pwosedi pibliye tou yon rapò ki reponn kòmantè yo resevwa. Se youn nan destinasyon sa yo, epi chak anons di si li aplike.</p>",
    public_input_explainer_limits_heading: "Limit patisipasyon an",
    public_input_explainer_limits_html: "<p>Yon repons yon ofisyèl se yon bagay apa de yon antre nan dosye a. Depoze yon kòmantè oswa bay temwayaj mete pawòl ou nan dosye a, epi okenn ofisyèl pa oblije reponn ou pèsonèlman. Sit sa a pa pwomèt yon repons konsa.</p><p>Yon konte kòmantè rete yon konte kòmantè. Yon enstitisyon peze sa yo di a kont lwa li travay anba li, kidonk sit sa a pa prezante okenn total kòmantè kòm sipò oswa opozisyon epi li pa trete kantite kòmantè kòm yon vòt.</p>",
    public_input_explainer_examples_heading: "Twa fason sa a mache nan reyalite",
    public_input_explainer_example_hearing: "Pale nan yon odyans Konsèy Vil la sou yon pwojè lwa, oswa voye temwayaj ekri.",
    public_input_explainer_example_hearing_surface: "Wè odyans ak reyinyon ki pwograme",
    public_input_explainer_example_rule: "Bay kòmantè sou règ yon ajans pwopoze anvan dat limit li ki pibliye a.",
    public_input_explainer_example_rule_surface: "Wè peryòd kòmantè règ ki ouvè",
    public_input_explainer_example_contract: "Bay kòmantè sou yon akòdman kontra pwopoze pandan peryòd kòmantè li a.",
    public_input_explainer_example_contract_surface: "Wè dat limit kòmantè kontra",
    public_input_explainer_official_source: "Sous ofisyèl: {source}",
    public_input_explainer_method_summary: "Ki kote eksplikasyon sa a soti",
    public_input_explainer_method_html: "<p>Chak egzanp anwo a mennen nan paj Vil la ki gouvène li, epi nan pati sit sa a ki bay lis dosye aktif nan kalite sa a. Eksplikasyon sa a dekri kijan pwosedi sa yo mache an jeneral; dat, estati, objektif ak chemen patisipasyon espesifik pou nenpòt nan yo rete sou pwòp anons li, akote lyen sous Rejis Minisipal li.</p>",
