    home_link: "Akèy",
    data_page_h1: "Done yo",
    about_using_html: "Kòmanse ak <a href=\"/guide/\">Sèvi ak CityScroll</a> pou jwenn yon dosye, swiv yon sijè oswa konprann prèv dèyè yon koneksyon. Gid la esplike tou kouvèti sous yo, enfòmasyon ki manke, siy avètisman ak tandans istorik.",
    about_maintainers: "Ekip antretyen",
    about_team_html: "Anna Bao, James Carroll, Dev Doshi ak Michael Sheehan okipe CityScroll. Kontakte ekip la nan <a href=\"mailto:team@cityscroll.org\">team@cityscroll.org</a>. Lojisyèl la gen kòd sous ouvè: <a href=\"https://github.com/cityscroll/cityscroll-app\">li kòd la sou GitHub</a> pou wè kijan sit la mache oswa kontribye yon chanjman.",
    about_access_html: "CityScroll vize respekte <b>WCAG 2.2 Nivo AA</b>. Si yon paj oswa yon kontwòl bloke aksè w, dekri li nan fòm kòmantè a pou nou ka egzamine pwoblèm nan.",
    about_destination_0: "Siy ak papòt",
    about_destination_1: "Tandans istorik",
    about_destination_2: "Tan pou etabli lis kandida",
    about_destination_3: "Tan pou vann pwopriyete",
    about_destination_4: "Pwogresyon privilèj fiskal",
    about_destination_5: "Istwa dosye zonaj",
    about_destination_6: "Istwa aplikan",
    about_h_what: "Kisa sa a ye",
    about_p_what_html: "CityScroll konekte piblikasyon ofisyèl Vil New York pou ede w konprann sa gouvènman vil la ap fè ak sa ou ka fè apre. Li rasanble dosye ki gen rapò pandan li kenbe lyen sou sous piblik yo. CityScroll endepandan epi li pa fè pati gouvènman vil la. Avi ofisyèl yo toujou se otorite pou dat, desizyon ak enstriksyon.",
    about_h_content: "Sou kontni nou an",
    about_p_content_html: "CityScroll sèvi ak entèlijans atifisyèl jeneratif (AI) pou prepare bouyon tit ak eksplikasyon nan lang senp. Yon moun revize epi korije tèks sa a anvan li pibliye. AI pa kreye oswa chanje dosye ofisyèl sit la montre yo.",
    about_flag_method_html: "Metòd nou pou siyale risk yo baze sou <a href=\"https://www.open-contracting.org/resources/red-flags-in-public-procurement-a-guide-to-using-data-to-detect-and-mitigate-risks/\" target=\"_blank\" rel=\"noopener noreferrer\">gid Open Contracting sou siy risk nan acha piblik<span class=\"sr-only\"> (ouvri nan yon nouvo onglet)</span></a>.",
