    data_p_lede_html: "Ansanm done City Record la, yon sèl kout je. Navigatè w chèche total an dirèk nan <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">NYC Open Data<span class=\"sr-only\"> (louvri nan yon nouvo fenèt)</span></a>. Anyen pa anrejistre sou sèvè a. Chif yo swiv <a href=\"api.html#upstream\">règ onètete yo</a>. Estatistik rete nan pwòp seksyon pa yo. Erè antre done ki gen plis chans se erè eskli — montan $10 milya oswa plis. Dat limit ki make plas pa konte kòm vrè.",
